const affUrl = 'assets/mn_MN.aff';
const dicUrl = 'assets/mn_MN.dic';
let spellChecker;
let lastMisspellings = new Map();

function setStatus(text) {
  const el = document.getElementById("status");
  if (el) el.innerText = text;
}

function renderSuggestions(misspellingsMap) {
  const container = document.getElementById("suggestions");
  const empty = document.getElementById("suggestions-empty");
  if (!container || !empty) return;

  container.innerHTML = "";
  const entries = Array.from(misspellingsMap.entries());

  if (entries.length === 0) {
    empty.style.display = "block";
    return;
  }

  empty.style.display = "none";

  for (const [word, suggestions] of entries) {
    const item = document.createElement("div");
    item.className = "mn-suggestion-item";

    const wordEl = document.createElement("div");
    wordEl.className = "mn-suggestion-item__word";
    wordEl.innerText = word;
    item.appendChild(wordEl);

    const actions = document.createElement("div");
    actions.className = "mn-suggestion-item__actions";

    const topSuggestions = (suggestions || []).slice(0, 8);
    if (topSuggestions.length === 0) {
      const none = document.createElement("div");
      none.className = "ms-font-s";
      none.style.color = "#666";
      none.innerText = "Санал олдсонгүй.";
      actions.appendChild(none);
    } else {
      for (const s of topSuggestions) {
        const btn = document.createElement("button");
        btn.type = "button";
        btn.className = "mn-suggestion-btn";
        btn.innerText = s;
        btn.addEventListener("click", () => replaceWordInDoc(word, s));
        actions.appendChild(btn);
      }
    }

    item.appendChild(actions);
    container.appendChild(item);
  }
}

async function replaceWordInDoc(fromWord, toWord) {
  try {
    setStatus(`"${fromWord}" → "${toWord}" солиж байна...`);
    await Word.run(async (context) => {
      const body = context.document.body;
      const results = body.search(fromWord, { matchWholeWord: true });
      results.load("items");
      await context.sync();

      results.items.forEach(r => {
        const replaced = r.insertText(toWord, Word.InsertLocation.replace);
        // Reset formatting back to "normal" after a correction
        // Apply on both the original range handle and the returned inserted range
        r.font.highlightColor = null;
        r.font.color = "Black";
        r.font.underline = Word.UnderlineType.none;

        replaced.font.highlightColor = null;
        replaced.font.color = "Black";
        replaced.font.underline = Word.UnderlineType.none;
      });
      await context.sync();
    });
    setStatus(`"${fromWord}" үг засагдлаа.`);
  } catch (e) {
    console.error("Засах үед алдаа гарлаа:", e);
    setStatus("Засах үед алдаа гарлаа.");
  }
}

Office.onReady((info) => {
  if (info.host === Office.HostType.Word) {
    document.getElementById("run").onclick = run;
    loadDictionary();
  }
});

async function loadDictionary() {
  try {
    console.log("Толь бичиг ачаалж байна...");

    // Lazy-load hunspell-asm only when needed
    const { loadModule } = await import('hunspell-asm');

    // 1. Файлуудыг ArrayBuffer хэлбэрээр татаж авах
    const [affRes, dicRes] = await Promise.all([
      fetch(affUrl),
      fetch(dicUrl)
    ]);

    const affBuffer = new Uint8Array(await affRes.arrayBuffer());
    const dicBuffer = new Uint8Array(await dicRes.arrayBuffer());

    // 2. Hunspell wasm module-г ачаалж, factory авах
    const factory = await loadModule();

    // 3. aff/dic файлуудыг wasm FS руу mount хийгээд spellchecker үүсгэх
    const affPath = factory.mountBuffer(affBuffer, "mn_MN.aff");
    const dicPath = factory.mountBuffer(dicBuffer, "mn_MN.dic");
    spellChecker = factory.create(affPath, dicPath);

    console.log("Монгол хэлний толь (WASM) амжилттай уншигдлаа!");
    setStatus("Алдаа шалгахад бэлэн.");
  } catch (error) {
    console.error("Алдаа гарлаа:", error);
    setStatus("Толь уншихад алдаа гарлаа.");
  }
}

export async function run() {
  return Word.run(async (context) => {
    if (!spellChecker) {
      console.error("Толь бичиг хараахан ачаалж дуусаагүй байна.");
      return;
    }

    const body = context.document.body;
    body.load("text");
    await context.sync();

    // Текстийг үгс болгон хуваах
    const words = body.text.split(/\s+/);
    const misspellings = new Map();

    for (let word of words) {
      const cleanWord = word.replace(/[.,\/#!$%\^&\*;:{}=\-_`~()]/g, "");

      if (cleanWord.length > 1) {
        // Hunspell-ээр шалгах
        const isCorrect = spellChecker.spell(cleanWord);

        if (!isCorrect) {
          if (!misspellings.has(cleanWord)) {
            const suggestions = spellChecker.suggest(cleanWord);
            misspellings.set(cleanWord, suggestions);
          }

          // Алдаатай үгийг Word дээр улаан wave underline-аар тодруулах
          const searchResults = body.search(cleanWord, { matchWholeWord: true });
          searchResults.load("font");
          await context.sync();

          searchResults.items.forEach(item => {
            item.font.underline = Word.UnderlineType.single; // Улаан wave underline (spell check мэт)
            item.font.underlineColor = "#FF0000";           // Улаан өнгө
          });
        }
      }
    }

    lastMisspellings = misspellings;
    renderSuggestions(lastMisspellings);
    console.log("Олдсон алдаанууд:", Array.from(misspellings.keys()));
    await context.sync();
  });
}